// --- Main Component ---

const ThreeNumbers: React.FC<ThreeNumbersProps> = ({
  backgroundColor = "#0A1128",
  transparentBackground = false,
  durationInSeconds = 8,
  headlineTop = "EVERY RAISE COMES DOWN TO",
  headlineBottom = "THREE NUMBERS:",
  headlineBottomColor = "#6aa1fc",
  items = [
    {
      number: "1",
      themeColor: "#4fb778",
      iconType: "magnet" as const,
      textPart1: "How many qualified ",
      highlight: "investor leads",
      textPart2: " you need each month",
    },
    {
      number: "2",
      themeColor: "#5b8cf6",
      iconType: "funnel" as const,
      textPart1: "How those leads ",
      highlight: "convert",
      textPart2: " through a structured funnel",
    },
    {
      number: "3",
      themeColor: "#9a60ed",
      iconType: "coins" as const,
      textPart1: "What each dollar of capital ",
      highlight: "costs",
      textPart2: " to acquire",
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Header Animations
  const headerOpacity = interpolate(frame, [10, 25], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const headerY = interpolate(frame, [10, 25], [40 * s, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  const subHeaderOpacity = interpolate(frame, [20, 35], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const subHeaderY = interpolate(frame, [20, 35], [40 * s, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          padding: `${80 * s}px ${120 * s}px`,
          boxSizing: "border-box",
        }}
      >
        {/* Header Section */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginBottom: 90 * s }}>
          <div
            style={{
              opacity: headerOpacity,
              transform: `translateY(${headerY}px)`,
              fontSize: 64 * s,
              fontFamily: montserratFamily,
              fontWeight: 800,
              color: "#fff",
              letterSpacing: 2 * s,
              textTransform: "uppercase",
              transition: "none",
            }}
          >
            {headlineTop}
          </div>
          <div
            style={{
              opacity: subHeaderOpacity,
              transform: `translateY(${subHeaderY}px)`,
              fontSize: 88 * s,
              fontFamily: montserratFamily,
              fontWeight: 800,
              color: headlineBottomColor,
              marginTop: 10 * s,
              textTransform: "uppercase",
              transition: "none",
            }}
          >
            {headlineBottom}
          </div>
        </div>

        {/* 3 Columns Section */}
        <div style={{ display: "flex", flexDirection: "row", width: "100%", justifyContent: "space-between", alignItems: "flex-start" }}>
          {items.map((item, i) => {
            const delay = 35 + i * 15;

            // Per-column animations
            const itemOpacity = interpolate(frame, [delay, delay + 15], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
            const itemY = interpolate(frame, [delay, delay + 15], [60 * s, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
            
            const numScale = spring({
              fps,
              frame: frame - delay - 5,
              config: { damping: 14, stiffness: 120 },
            });

            const iconScale = spring({
              fps,
              frame: frame - delay - 12,
              config: { damping: 12, stiffness: 140 },
            });

            const textOpacity = interpolate(frame, [delay + 15, delay + 30], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

            return (
              <div
                key={i}
                style={{
                  width: "30%",
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  opacity: itemOpacity,
                  transform: `translateY(${itemY}px)`,
                  transition: "none",
                }}
              >
                {/* Number & Icon Row */}
                <div
                  style={{
                    display: "flex",
                    flexDirection: "row",
                    alignItems: "center",
                    justifyContent: "center",
                    gap: 15 * s,
                    height: 260 * s,
                    marginBottom: 40 * s,
                  }}
                >
                  <div
                    style={{
                      fontSize: 260 * s,
                      fontFamily: montserratFamily,
                      fontWeight: 800,
                      color: item.themeColor,
                      lineHeight: 1,
                      transform: `scale(${numScale})`,
                      transformOrigin: "bottom right",
                      transition: "none",
                    }}
                  >
                    {item.number}
                  </div>
                  <div style={{ transform: `scale(${iconScale})`, transformOrigin: "center left", transition: "none" }}>
                    {item.iconType === "magnet" && <MagnetIcon color={item.themeColor} s={s} />}
                    {item.iconType === "funnel" && <FunnelIcon color={item.themeColor} s={s} />}
                    {item.iconType === "coins" && <CoinsIcon color={item.themeColor} s={s} />}
                  </div>
                </div>

                {/* Text Block */}
                <div
                  style={{
                    fontFamily: interFamily,
                    fontSize: 36 * s,
                    color: "#fff",
                    textAlign: "left",
                    lineHeight: 1.4,
                    opacity: textOpacity,
                    maxWidth: "95%",
                    transition: "none",
                  }}
                >
                  {item.textPart1}
                  <span style={{ color: item.themeColor, fontWeight: 700 }}>{item.highlight}</span>
                  {item.textPart2}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ThreeNumbers;